make(4, "下列哪一對數互質？", {"A":"14 與 21", "B":"18 與 27", "C":"25 與 35", "D":"16 與 25"}, "D", "16=2⁴、25=5²，沒有共同質因數，最大公因數為 1，因此互質的是 D。", "不必列出所有倍數，只要比較兩數的質因數是否有交集。", ["分解 16=2⁴。", "分解 25=5²。", "兩者沒有共同質因數。", "所以最大公因數為 1。", "因此選 D。"], "easy"),
make(5, "若 n=2³×3×5，則 n 的值為何？", {"A":"90", "B":"120", "C":"180", "D":"240"}, "B", "2³×3×5=8×3×5=120，正確答案為 B。", "先計算指數，再依序相乘並核對選項。", ["計算 2³=8。", "把式子改成 8×3×5。", "先算 8×3=24。", "24×5=120。", "所以選 B。"], "easy"),
make(6, "72 的正因數共有幾個？", {"A":"8 個", "B":"10 個", "C":"12 個", "D":"14 個"}, "C", "72=2³×3²，正因數個數=(3+1)(2+1)=12，所以選 C。", "質因數指數加一後相乘，即可得到正因數個數。", ["分解 72=2³×3²。", "2 的指數可選 0、1、2、3，共 4 種。", "3 的指數可選 0、1、2，共 3 種。", "因數總數為 4×3=12。", "所以選 C。"], "medium"),
make(7, "甲燈每 8 秒閃一次，乙燈每 12 秒閃一次；兩燈同時閃後，至少幾秒會再次同時閃？", {"A":"16 秒", "B":"20 秒", "C":"24 秒", "D":"96 秒"}, "C", "再次同時閃的時間是 8 與 12 的最小公倍數；LCM(8,12)=24，所以選 C。", "週期再次重合要找最小公倍數，不是最大公因數。", ["列出兩個週期 8 與 12。", "分解 8=2³、12=2²×3。", "最小公倍數取 2³×3。", "計算得到 24 秒。", "所以選 C。"], "medium"),
make(8, "84 與 126 的最大公因數為何？", {"A":"14", "B":"21", "C":"28", "D":"42"}, "D", "84=2²×3×7、126=2×3²×7，共同部分為 2×3×7=42，選 D。", "分解後只保留兩數共同出現的質因數與較小指數。", ["分解 84=2²×3×7。", "分解 126=2×3²×7。", "共同質因數為 2、3、7。", "取較小次方得到 2×3×7=42。", "所以選 D。"], "medium"),
